function unseenCells(m: number, n: number, guards: number[][], walls: number[][]): number {
  const grid = Array.from({ length: m }, () => new Array(n).fill(0));
  for (const [r, c] of guards) grid[r][c] = 1;
  for (const [r, c] of walls) grid[r][c] = 2;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let count = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] !== 0) continue;
      let seen = false;
      for (const [dr, dc] of dirs) {
        let i = r + dr, j = c + dc;
        while (i >= 0 && i < m && j >= 0 && j < n && grid[i][j] === 0) { i += dr; j += dc; }
        if (i >= 0 && i < m && j >= 0 && j < n && grid[i][j] === 1) { seen = true; break; }
      }
      if (!seen) count++;
    }
  }
  return count;
}

