function unseenCells(m: number, n: number, guards: number[][], walls: number[][]): number {
  const grid = new Uint8Array(m * n); // 0 empty, 1 guard, 2 wall
  const seen = new Uint8Array(m * n);
  for (const [r, c] of guards) grid[r * n + c] = 1;
  for (const [r, c] of walls) grid[r * n + c] = 2;
  const sweep = (start: number, step: number, len: number): void => {
    let watching = false;
    for (let k = 0, idx = start; k < len; k++, idx += step) {
      if (grid[idx] === 1) watching = true;
      else if (grid[idx] === 2) watching = false;
      else if (watching) seen[idx] = 1;
    }
  };
  for (let r = 0; r < m; r++) {
    sweep(r * n, 1, n);
    sweep(r * n + n - 1, -1, n);
  }
  for (let c = 0; c < n; c++) {
    sweep(c, n, m);
    sweep((m - 1) * n + c, -n, m);
  }
  let count = 0;
  for (let i = 0; i < m * n; i++) if (grid[i] === 0 && !seen[i]) count++;
  return count;
}

