        seen = [False] * (m * n)
        for r, c in guards:
            grid[r * n + c] = 1
        for r, c in walls:
            grid[r * n + c] = 2

        def sweep(start, step, length):
            watching = False
            idx = start
            for _ in range(length):
                g = grid[idx]
                if g == 1:
                    watching = True
                elif g == 2:
                    watching = False
                elif watching:
                    seen[idx] = True
                idx += step

        for r in range(m):
            sweep(r * n, 1, n)
            sweep(r * n + n - 1, -1, n)
        for c in range(n):
            sweep(c, n, m)
            sweep((m - 1) * n + c, -n, m)
        return sum(1 for i in range(m * n) if grid[i] == 0 and not seen[i])

